<?php
namespace App\Services;
use App\Models\CommunicationDelivery;use Illuminate\Support\Facades\{DB,Http,Log,Mail};
class ChannelDeliveryService{public function send(CommunicationDelivery $d):array{$c=$d->campaign;$body=str_replace(['{name}','{student}','{date}'],[$d->recipient_name,$d->recipient_name,now()->format('d-m-Y')],$c->body);return match($d->channel){'sms'=>$this->http('sms',$d->destination,$body),'whatsapp'=>$this->http('whatsapp',$d->destination,$body),'push'=>$this->http('push',$d->destination,$body),'email'=>$this->email($d->destination,$c->subject?:$c->name,$body),default=>throw new \RuntimeException('Unsupported channel.')};}
 private function http(string $channel,string $to,string $body):array{$cfg=config("services.$channel");if(($cfg['driver']??'log')==='log'){Log::info(strtoupper($channel).' SIMULATED',compact('to','body'));return ['status'=>'simulated','id'=>null,'response'=>'Logged locally'];}$url=$cfg['url']??null;throw_unless($url,new \RuntimeException(strtoupper($channel).' provider URL is not configured.'));if($channel==='push'){$subscription=DB::table('push_subscriptions')->where('endpoint',$to)->first();$payload=['subscription'=>['endpoint'=>$to,'keys'=>['p256dh'=>$subscription?->public_key,'auth'=>$subscription?->auth_token]],'title'=>'School notification','body'=>$body,'url'=>'/parent-services'];}else{$payload=['api_key'=>$cfg['api_key']??null,'senderid'=>$cfg['sender_id']??null,'number'=>$to,'message'=>$body];}$r=Http::timeout(20)->retry(2,400)->post($url,$payload);$r->throw();return ['status'=>'sent','id'=>$r->json('message_id')??$r->json('id'),'response'=>$r->body()];}
 private function email(string $to,string $subject,string $body):array{Mail::raw($body,fn($m)=>$m->to($to)->subject($subject));return ['status'=>'sent','id'=>null,'response'=>'Accepted by configured mail transport'];}}
